    /// Nationalities used for foreign players, roughly by how common they are.
    static let foreignNationalities: [(code: String, weight: Double)] = [
        ("BR", 3), ("FR", 3), ("ES", 2), ("PT", 2), ("AR", 2), ("NL", 1.5), ("DE", 1.5),
        ("EN", 1.5), ("IT", 1.5), ("SN", 1.5), ("NG", 1.5), ("TR", 1)
    ]

    static func name(for nationality: String, rng: inout SeededRandom) -> (first: String, last: String) {
        let pool = pools[nationality] ?? pools["EN"]!
        return (rng.pick(pool.firstNames), rng.pick(pool.lastNames))
    }

    static func randomNationality(domestic: String, domesticShare: Double, rng: inout SeededRandom) -> String {
        if rng.chance(domesticShare) { return domestic }
        let options = foreignNationalities.filter { $0.code != domestic }
        let index = rng.weightedIndex(options.map(\.weight)) ?? 0
        return options[index].code
    }
}
